fn map_p(b_: ScreenPt, s_: f64, ht: f64, x: f64, y: f64) ScreenPt {
    return cx_new(ScreenPtS{ .x = (b_.x + ((s_ * x) * ht)), .y = (b_.y - (y * ht)) });
}

fn mapped_pts(b_: ScreenPt, s_: f64, ht: f64, ps: *CxList(EmojiPt), i_: i64) *CxList(ScreenPt) {
    return (if ((i_ >= cx_list_len(ps))) cx_ll_empty(ScreenPt) else cx_ll_concat(cx_ll_of(ScreenPt, &[_]ScreenPt{ map_p(b_, s_, ht, cx_list_at(ps, i_).x, cx_list_at(ps, i_).y) }), mapped_pts(b_, s_, ht, ps, (i_ +% 1))));
}

fn max_critter_pts() i64 {
    return 512;
}

fn critter_poly(b_: ScreenPt, s_: f64, ht: f64, poly: EmojiPoly) *CxList(DrawCmd) {
    return (if ((cx_list_len(poly.pts) > max_critter_pts())) cx_ll_empty(DrawCmd) else push_poly(poly.color, mapped_pts(b_, s_, ht, poly.pts, 0)));
}

fn critter_polys(b_: ScreenPt, s_: f64, ht: f64, ps: *CxList(EmojiPoly), i_: i64) *CxList(DrawCmd) {
    return (if ((i_ >= cx_list_len(ps))) cx_ll_empty(DrawCmd) else cx_ll_concat(critter_poly(b_, s_, ht, cx_list_at(ps, i_)), critter_polys(b_, s_, ht, ps, (i_ +% 1))));
}

fn critter_draw(right: f64, forward: f64, height: f64, cp_: i64, face_right: bool, cf: f64, view_w: f64) *CxList(DrawCmd) {
    return b0: { const base_ = project(cx_new(Vec3S{ .right = right, .forward = forward, .height = @as(f64, @bitCast(@as(i64, 0))) }), cf, view_w); break :b0 b1: { const top_ = project(cx_new(Vec3S{ .right = right, .forward = forward, .height = height }), cf, view_w); break :b1 b2: { const h_: f64 = (base_.y - top_.y); break :b2 (if ((h_ < @as(f64, @bitCast(@as(i64, 4607182418800017408))))) cx_ll_empty(DrawCmd) else critter_polys(base_, @as(f64, (if (face_right) (@as(f64, @bitCast(@as(i64, 0))) - @as(f64, @bitCast(@as(i64, 4607182418800017408)))) else @as(f64, @bitCast(@as(i64, 4607182418800017408))))), h_, (if ((cp_ == 129414)) duck_polys() else (if ((cp_ == 128024)) elephant_polys() else (if ((cp_ == 129426)) giraffe_polys() else (if ((cp_ == 129427)) zebra_polys() else (if ((cp_ == 129423)) rhino_polys() else (if ((cp_ == 128002)) bull_polys() else (if ((cp_ == 128004)) cow_polys() else (if ((cp_ == 128022)) pig_polys() else cx_ll_empty(EmojiPoly))))))))), 0)); }; }; };
